for _, vector in ipairs(VECTORS) do
    local id, message, expected = vector[1], vector[2], vector[3]
    local p = ir.protocol.get(id)
    local values, info = p:decode(ir.frame({carrier_hz = 38000, pulses_us = vector[4]}))
    assert(values, id .. " " .. message .. ": " .. tostring(info))
    assert(info.message == message and info.checked, id .. ": message " .. info.message)
    for field, value in pairs(expected) do assert(values[field] == value, id .. " " .. message .. ": " .. field) end
    for field in pairs(values) do assert(expected[field] ~= nil, id .. " " .. message .. ": unexpected " .. field) end
    local again = p:decode(p:encode(values))
    for field, value in pairs(expected) do assert(again[field] == value, id .. " " .. message .. ": re-encode " .. field) end
end
print("[ir_capture_vectors] passed; " .. #VECTORS .. " captured frames")
